class Solution {
public:
    vector<int> findEvenNumbers(vector<int>& digits) {
        int freq[10] = {0};
        for (int d : digits) freq[d]++;

        vector<int> result;
        for (int num = 100; num <= 998; num += 2) {
            int a = num / 100;
            int b = (num / 10) % 10;
            int c = num % 10;
            int need[10] = {0};
            need[a]++; need[b]++; need[c]++;
            bool ok = true;
            for (int i = 0; i < 10; i++) {
                if (need[i] > freq[i]) { ok = false; break; }
            }
            if (ok) result.push_back(num);
        }
        return result;
    }
};
